import { useState } from "react";
import { Badge, DataTable, type ColumnDef } from "@godxjp/ui/data-display";
import { EmptyState } from "@godxjp/ui/data-display";

type Invoice = {
  id: string;
  customer: string;
  amount: number;
  status: "paid" | "pending" | "overdue";
};

const columns: ColumnDef<Invoice>[] = [
  { key: "id", header: "Invoice #", width: "w-32" },
  { key: "customer", header: "Customer" },
  {
    key: "status",
    header: "Status",
    render: (row) => (
      <Badge
        tone={
          row.status === "paid" ? "success" : row.status === "overdue" ? "destructive" : "warning"
        }
      >
        {row.status}
      </Badge>
    ),
  },
  { key: "amount", header: "Amount", align: "right", sortable: true },
];

export default function InvoiceList({
  invoices,
  loading,
}: {
  invoices: Invoice[];
  loading: boolean;
}) {
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [sort, setSort] = useState<{ key: string; direction: "asc" | "desc" } | undefined>();

  return (
    <DataTable
      data={invoices}
      columns={columns}
      getRowId={(row) => row.id}
      selectable
      selected={selected}
      onSelectChange={setSelected}
      sort={sort}
      onSortChange={setSort}
      loading={loading}
      empty={
        <EmptyState
          title="No invoices found"
          description="Adjust your filters or create a new invoice."
        />
      }
    >
      <DataTable.Toolbar>
        <DataTable.BulkActions>
          <button type="button" onClick={() => setSelected(new Set())}>
            Mark paid
          </button>
        </DataTable.BulkActions>
        <DataTable.DensityToggle />
      </DataTable.Toolbar>
    </DataTable>
  );
}

